'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?esc(u.href):'#'}catch{return '#'}};
const link=(url,title)=>`<a href="${safeURL(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;
const stateKey='shanhe-v1',M=TravelMoney,Cities=TravelCities,I18N=TravelI18n;
let foodLimit=8,foodPlan=[],foodRoutes=[];
const foodRouteKey=g=>g.id||g.city+":"+g.title;
let DATA,lang='zh',currency='CNY',region='all',city='all',theme='all',limit=12,compare=[],plan=[],lastFocus=null,detailReturnView='explore',detailId=null,storageOK=true;
const amountsCNY={roomRate:null,mealDaily:null,transitDaily:null,charterCost:0,intercityCost:0,longTransport:null,extraCost:0};let customRates={},budgetSettings={rooms:null,nights:null};
const englishUI=()=>!I18N.chinese(lang);
const t=(zh,en)=>I18N.resolve(zh,en,lang);
const L=(o,k)=>I18N.field(o,k,lang);
const regionName=(id,full=false)=>englishUI()?I18N.translate(REGION_EN[id]?.[full?1:0]||id,lang):I18N.translate(full?DATA.regions.find(r=>r.id===id)?.name||id:id,lang);
const term=s=>I18N.translate(englishUI()?(TERMS_EN[s]||s):s,lang);
const seasons=s=>englishUI()?(s==='全年'?t('全年','Year-round'):[...s].map(term).join(' / ')):I18N.translate(s,lang);
const getRates=()=>Object.fromEntries(M.codes.map(c=>[c,c==='CNY'?1:customRates[c]?.rate||M.snapshot.rates[c]]));
const money=n=>M.format(n,currency,lang,getRates());
const find=id=>DATA.destinations.find(d=>d.id===id);
const enCount=(n,word)=>`${n} ${word}${n===1?"":"s"}`;
function nval(id,min,max){const v=Number($('#'+id).value),n=Math.max(min,Math.min(max,Number.isFinite(v)?v:min));return ['people','days','planPeople','planDays'].includes(id)?Math.round(n):n}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function loadState(){try{
  const d=JSON.parse(localStorage.getItem(stateKey)||'{}');
  lang=I18N.codes.includes(d.preferences?.lang)?d.preferences.lang:I18N.normalize(navigator.language);
  currency=M.codes.includes(d.preferences?.currency)?d.preferences.currency:'CNY';
  if(DATA.regions.some(r=>r.id===d.filters?.region))region=d.filters.region;
  if(Cities.options(DATA,region).some(c=>c.name===d.filters?.city))city=d.filters.city;
  compare=[...new Set(Array.isArray(d.compare)?d.compare:[])].filter(id=>typeof id==='string'&&find(id)).slice(0,3);
  plan=(Array.isArray(d.plan)?d.plan:[]).filter(p=>p&&find(p.id)).map(p=>({id:p.id,nights:TravelBudget.integer(p.nights,null,1,30),...TravelTickets.planTicket(find(p.id),p),ticketCount:TravelBudget.integer(p.ticketCount,null,0,10000)})).filter((p,i,a)=>a.findIndex(q=>q.id===p.id)===i);
  for(const id of ['people','days','planPeople','planDays','startDate'])if(d.settings?.[id]!==undefined)$('#'+id).value=d.settings[id];
  for(const id of Object.keys(amountsCNY)){const saved=d.amountsCNY||d.settings||{},v=Object.hasOwn(saved,id)?saved[id]:amountsCNY[id];amountsCNY[id]=TravelBudget.amount(v)}
  if((d.version||0)<4){amountsCNY.extraCost=TravelBudget.migrateExtras(d.plan,amountsCNY.extraCost);for(const id of ['charterCost','intercityCost','extraCost'])if(amountsCNY[id]===null)amountsCNY[id]=0}
  foodPlan=TravelBudget.normalizeFoods(d.foodPlan).filter(p=>DATA.foods.some(f=>f.id===p.id&&f.recommendationStatus!=='research-only'));
  foodRoutes=[...new Set(Array.isArray(d.foodRoutes)?d.foodRoutes:[])].filter(key=>(DATA.foodGuides||[]).some(g=>foodRouteKey(g)===key));
  budgetSettings={rooms:TravelBudget.integer(d.budgetSettings?.rooms,null,0,30),nights:TravelBudget.integer(d.budgetSettings?.nights,null,0,365)};
  for(const[c,v]of Object.entries(d.customRates||{}))if(M.codes.includes(c)&&c!=='CNY'&&M.validRate(v?.rate)&&/^\d{4}-\d{2}-\d{2}$/.test(v.date||''))customRates[c]={rate:v.rate,date:v.date};
}catch{storageOK=false}}
function save(){try{
  const settings={};for(const id of ['people','days','planPeople','planDays','startDate'])settings[id]=$('#'+id).value;
  Object.assign(settings,amountsCNY);localStorage.setItem(stateKey,JSON.stringify({version:5,compare,plan,foodPlan,foodRoutes,settings,amountsCNY,budgetSettings,customRates,preferences:{lang,currency},filters:{region,city}}));
}catch{storageOK=false;toast(t('浏览器存储不可用，请导出行程备份。','Browser storage is unavailable. Export your itinerary as a backup.'))}}
const staticNodes=[],staticAttrs=[];
function captureStatic(){
  const skip='script,style,#language,#translationNotice,#fxSource,#cards,#detailBody,#comparison,#planSummary,#planList,#diningTotals,#diningList,#diningRoutes,#foodList,#foodGuides,#foodCity,#provinceList,#provinceSelect,#citySelect,#cityCoverage,#coverageStats,#provinceProgress,#cityAllocation,#toast,#resultCount,#resultsTitle,#foodRegion,#fxStatus,#fxRateUnit,#provinceUpdate,[data-total-destinations],[data-currency-unit],#budget';
  const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walk.nextNode()){const n=walk.currentNode;if(n.parentElement?.closest(skip))continue;if(n.nodeValue.trim())staticNodes.push([n,n.nodeValue])}
  for(const el of $$('[placeholder],[aria-label],[alt]'))for(const a of ['placeholder','aria-label','alt'])if(el.hasAttribute(a))staticAttrs.push([el,a,el.getAttribute(a)]);
}
function applyStatic(){
  document.documentElement.lang=I18N.locale(lang);document.documentElement.dataset.language=lang;document.title=t('I wanna go to China · 中国旅行指南','I wanna go to China · Travel guide');
  for(const[n,original]of staticNodes){const key=original.trim();n.nodeValue=I18N.chinese(lang)?I18N.translate(original,lang):original.replace(key,()=>I18N.translate(STATIC_EN[key]||key,lang))}
  for(const[el,a,original]of staticAttrs)el.setAttribute(a,I18N.chinese(lang)?I18N.translate(original,lang):I18N.translate(STATIC_EN[original]||original,lang));
  $('#language').value=lang;$('#currency').value=currency;$$('[data-currency-unit]').forEach(el=>el.textContent=currency);

  $('#translationNotice').hidden=I18N.chinese(lang)||lang==='en';$('#translationNotice').textContent=t('自动译文，仅辅助阅读；预订前请核对中文店名、地址和原始来源。','Machine-translated reading aid. Check Chinese names, addresses and original sources before booking.');
  $('#fxSource').href=M.reference(currency).url;$('#fxSource').textContent=M.reference(currency).source+' · '+M.reference(currency).date+' ↗';
  $('#fxRateUnit').textContent=currency;$('#customRate').disabled=currency==='CNY';$('#saveRate').disabled=currency==='CNY';$('#resetRate').disabled=!customRates[currency];
  $('#customRate').value=getRates()[currency].toFixed(8).replace(/0+$/,'').replace(/\.$/,'');
  const reference=M.reference(currency),custom=customRates[currency];$('#fxStatus').textContent=custom?t(`1 CNY = ${custom.rate} ${currency} · 自定义预算汇率 · ${custom.date}`,`1 CNY = ${custom.rate} ${currency} · Custom planning rate · ${custom.date}`):(currency==='RUB'?t('俄罗斯央行参考汇率','Bank of Russia reference rate')+' · '+reference.date+' · '+t('非实时报价','Not live quotes'):t(`欧洲央行参考汇率 · ${reference.date} · 非实时报价`,`ECB reference rates · ${reference.date} · Not live quotes`));
  const ages=Math.floor((Date.now()-Date.parse(reference.date+'T00:00:00Z'))/86400000);$('#fxStale').textContent=!custom&&ages>7?t('参考汇率已超过 7 天，请按出行时汇率复核。','These reference rates are over 7 days old. Check the rate for your travel dates.'):'';
  const selected=$('#foodRegion').value;$('#foodRegion').innerHTML=`<option value="all">${t('全部已收录地区','All covered regions')}</option>`+[...new Set(DATA.foods.map(f=>f.region))].map(r=>`<option value="${esc(r)}">${esc(regionName(r))}</option>`).join('');$('#foodRegion').value=selected||'all';
  for(const id of Object.keys(amountsCNY))$('#'+id).value=amountsCNY[id]===null?'':Number(M.convert(amountsCNY[id],currency,getRates()).toFixed(2));
  $('#language').setAttribute('aria-label',t('语言','Language'));$('#currency').setAttribute('aria-label',t('显示货币','Display currency'));
  $('#customRate').setAttribute('aria-label',t('每 1 人民币对应的所选货币数量','Exchange rate per 1 CNY'));
}
function counters(){$('#compareCount').textContent=compare.length;$('#planCount').textContent=plan.length+foodPlan.length}
function showView(name){if(!['explore','food','compare','plan','evidence'].includes(name))name='explore';$$('.view').forEach(e=>e.classList.toggle('hidden',e.id!==name));$$('nav [data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===name));if(location.hash!=='#'+name)history.replaceState(null,'','#'+name);if(name==='food')renderFood();if(name==='compare')renderCompare();if(name==='plan')renderPlan();window.scrollTo({top:0,behavior:'smooth'})}
function cityName(name){const c=Cities.options(DATA,region).find(c=>c.name===name);return c?L(c,'name'):name}
function cityChildren(r){if(region!==r.id)return '';const cs=Cities.options(DATA,r.id);if(!cs.length)return '';return `<div class="city-children" role="group" aria-label="${esc(t('选择城市','Choose a city'))}"><button class="city-choice ${city==='all'?'selected':''}" data-city="all" aria-pressed="${city==='all'}">${t('全省城市','All cities')}</button>${cs.map(c=>{return `<button class="city-choice ${city===c.name?'selected':''}" data-city="${esc(c.name)}" aria-pressed="${city===c.name}"><span>${esc(L(c,'name'))}</span></button>`}).join('')}</div>`}
function renderCityControls(){
 $('#provinceSelect').innerHTML=`<option value="all">${t('全部省份与地区','All provincial regions')}</option>`+DATA.regions.map(r=>`<option value="${esc(r.id)}">${esc(regionName(r.id,true))}</option>`).join('');$('#provinceSelect').value=region;
 const cs=Cities.options(DATA,region);if(!cs.some(c=>c.name===city))city='all';$('#citySelect').disabled=region==='all'||!cs.length;
 $('#citySelect').innerHTML=`<option value="all">${region==='all'?t('请先选择省份','Choose a province first'):cs.length?t('全部城市','All cities'):t('城市资料逐省补充','City records coming by province')}</option>`+cs.map(c=>{return `<option value="${esc(c.name)}">${esc(L(c,'name'))}</option>`}).join('');$('#citySelect').value=city;
 const box=$('#cityCoverage'),target=Cities.minimum(DATA);if(city!=='all'){const s=Cities.stats(DATA,region,city);box.innerHTML=`<b>${esc(cityName(city))} · ${t(`已收录 ${s.count} 个景点`,`${s.count} attraction entries`)}</b><span>${t(`每城至少 ${target} 个，不设数量上限。详细攻略 ${s.deep} 个，其余待核实项见详情。`,`Minimum ${target} per city, with no upper limit. ${s.deep} detailed guides; remaining verification gaps are shown on each entry.`)}</span>`}
 else if(cs.length){const complete=cs.filter(c=>Cities.stats(DATA,region,c.name).ready).length;box.innerHTML=`<b>${t(`${complete}/${cs.length} 城达到至少 ${target} 个景点的收录标准`,`${complete}/${cs.length} cities meet the minimum of ${target} attractions`)}</b><span>${t(`至少 ${target} 个是最低标准，不是数量上限，景点将持续增加。待调研线索不计入，实时信息核实状态见详情。`,`The minimum of ${target} is not a cap; more attractions will be added. Research leads are excluded; see entries for verification status.`)}</span>`}
 else box.innerHTML=`<b>${t(`每城至少收录 ${target} 个景点`,`Minimum ${target} attraction entries per city`)}</b><span>${t(`至少 ${target} 个是起点，不是上限。广东城市目录持续扩充，其他地区逐省补充。`,`At least ${target} is a starting point, not a cap. Guangdong will keep growing; other regions will follow province by province.`)}</span>`;
}
function selectRegion(value,latest=false){region=DATA.regions.some(r=>r.id===value)?value:'all';city='all';if(latest)$('#sort').value='recent';limit=12;renderRegions();renderCards();save();showView('explore')}
function selectCity(value){city=Cities.options(DATA,region).some(c=>c.name===value)?value:'all';limit=12;renderRegions();renderCards();save();showView('explore')}
function renderRegions(){$$('[data-total-destinations]').forEach(e=>e.textContent=DATA.destinations.length);const groups=[...new Set(DATA.regions.map(r=>r.area))];$('#provinceList').innerHTML=groups.map(a=>`<div class="area-group"><div class="area-label">${esc(term(a))}</div>${DATA.regions.filter(r=>r.area===a).map(r=>`<button class="province ${region===r.id?'selected':''}" data-region="${esc(r.id)}" aria-expanded="${region===r.id}">${esc(regionName(r.id))}<span>${DATA.destinations.filter(d=>d.region===r.id).length}</span></button>${cityChildren(r)}`).join('')}</div>`).join('');$('.province.all').classList.toggle('selected',region==='all');renderCityControls()}

function photo(d,hero=false){return d.image?`<img src="${esc(d.image.path)}" alt="${esc(d.image.en?L(d.image,'caption'):(englishUI()?L(d,'name')+' · reference photo':d.image.caption))}" ${hero?'':'loading="lazy"'} decoding="async"><a href="${safeURL(d.image.url)}" target="_blank" rel="noopener noreferrer">${t('实景','Photo')} · ${d.image.rightsStatus==='source-copyright'?t('图片来源','Photo source'):esc(d.image.author).slice(0,35)}</a>`:`<div class="text-cover"><strong>${esc(L(d,'name'))}</strong><span>${t('实景照片待补核','Photo research pending')}</span></div>`}
function matches(d,q){return [d.name,d.region,d.city||'',d.location,d.description,d.food,L(d,'name'),L(d,'description'),L(d,'location'),L(d,'food'),...Object.values(d.en||{}),regionName(d.region,true)].join(' ').toLowerCase().includes(q)}
function renderCards(){
  const q=$('#search').value.trim().toLowerCase(),season=$('#month').value;
  let list=DATA.destinations.filter(d=>Cities.accepts(d,region,city)&&(theme==='all'||d.theme===theme)&&(!q||matches(d,q))&&(season==='all'||d.season==='全年'||d.season.includes(season))&&(!$('#withReviews').checked||d.reviews));
  if($('#sort').value==='recent')list.sort((a,b)=>(b.researchBatch||0)-(a.researchBatch||0));else if($('#sort').value==='evidence')list.sort((a,b)=>(b.reviews?2:0)+(b.sources.length?1:0)-((a.reviews?2:0)+(a.sources.length?1:0)));else list.sort((a,b)=>L(a,'name').localeCompare(L(b,'name'),I18N.locale(lang)));
  $('#resultsTitle').textContent=city!=='all'?(city===region?cityName(city):cityName(city)+' · '+regionName(region)):region==='all'?t('探索中国','Explore China'):regionName(region,true);$('#resultCount').textContent=t(`${list.length} 个目的地${q?' · 搜索结果':''}`,`${list.length} destinations${q?' · Search results':''}`);
  renderProvinceUpdate();
  $('#cards').innerHTML=list.slice(0,limit).map(d=>`<article class="card"><div class="card-photo">${photo(d)}${ticketBadge(d)}<span class="type-pill">${esc(term(d.theme))}</span></div><div class="card-content"><div class="card-loc">${esc(regionName(d.region))} · ${esc(L(d,'location'))}</div><button class="card-title" data-detail="${d.id}"><h3>${esc(L(d,'name'))}</h3></button>${englishUI()?`<small class="original-name" lang="zh-CN">${esc(d.name)} · ${esc(d.location)}</small>`:''}<p class="card-description">${esc(L(d,'description'))}</p><div class="tags">${d.researchBatch&&d.researchBatch===DATA.provinceUpdates?.[d.region]?.batch?`<span class="tag good">${t('最新补充','LATEST ADDITION')}</span>`:''}<span class="tag">${esc(seasons(d.season))}</span><span class="tag ${d.reviews?'good':''}">${d.reviews?t('有评价资料','Review sources'):esc(term(d.tier))}</span></div><div class="card-bottom"><div><div class="price-label">${t('整趟费用在行程中统一计算','Calculate trip costs in your itinerary')}</div></div><div class="card-actions"><button class="iconbtn ${compare.includes(d.id)?'on':''}" data-compare="${d.id}" aria-label="${esc(t('加入或移除对比：','Toggle comparison: ')+L(d,'name'))}">${compare.includes(d.id)?'✓':'＋'} ${t('对比','Compare')}</button><button class="iconbtn ${plan.some(p=>p.id===d.id)?'on':''}" data-plan="${d.id}" aria-label="${esc(t('加入行程：','Add to itinerary: ')+L(d,'name'))}">${plan.some(p=>p.id===d.id)?'✓':'＋'} ${t('行程','Plan')}</button></div></div></div><button class="card-detail" data-detail="${d.id}"><span>${d.sources.length?t(`${d.sources.length} 个资料来源`,`${d.sources.length} sources`):t('详细资料待调研','Research pending')}</span><span>${t('查看攻略 →','View guide →')}</span></button></article>`).join('');
  $('#empty').classList.toggle('hidden',list.length>0);$('#loadMore').classList.toggle('hidden',list.length<=limit);
  const party=$('#party').value;$('#partyNote').classList.toggle('hidden',!['family','senior'].includes(party));$('#partyNote').textContent=party==='family'?t('已选择带孩子：母婴室、儿童票与护栏尚未逐项核实，不自动标记“亲子友好”。','Traveling with children: nursery facilities, child tickets and safety barriers have not all been verified; no automatic family-friendly ranking is applied.'):t('已选择带长辈：无障碍设施、坡度与休息点尚未逐项核实，请确认体力与交通。','Traveling with older adults: accessibility, slopes and rest stops have not all been verified. Check walking effort and transport before booking.');
}
function toggleCompare(id){if(compare.includes(id)){compare=compare.filter(x=>x!==id);toast(t('已移出对比','Removed from comparison'))}else{if(compare.length>=3){toast(t('最多比较 3 个目的地，请先移除一个。','Compare up to 3 destinations. Remove one before adding another.'));return}compare.push(id);toast(t('已加入对比，可在顶部查看','Added. Open Compare in the navigation.'))}save();counters();renderCards();renderCompare()}
function addPlan(id){if(plan.some(p=>p.id===id)){toast(t('这个目的地已经在行程里','This destination is already in your itinerary.'));return}plan.push({id,nights:null,...TravelTickets.planTicket(find(id)),ticketCount:null});save();counters();renderCards();renderPlan();toast(t('已加入行程，已确认的单一门票已自动填写','Added. Verified single-ticket prices are filled automatically.'))}
function foodPrice(f){if(!f.priceCNY)return t('价格待核实','Price not verified');const p=f.priceCNY;return `${p.historical?t('历史参考约 ','Historical reference: about '):''}${money(p.low)}${p.high!==p.low?' – '+money(p.high):''}${t(' / 人',' / person')}`}
function foodCard(f){const original=L(f,'price'),cityEn=DATA.cities.find(c=>c.region===f.region&&c.name===f.city)?.en.name,place=englishUI()?(cityEn||DATA.destinations.find(d=>d.name===f.place)?.en?.name||f.place):f.city||f.place,sources=f.sources||[{platform:t('原始来源','Original source'),url:f.url}];return `<article class="food-card"><div class="food-card-top"><div class="eyebrow">${esc(regionName(f.region))} / ${esc(place)}</div><span class="food-kind">${f.evidenceLabel?esc(L(f,'evidenceLabel')):f.localSpecialty?t('当地特色 · 候选','LOCAL SPECIALTY · CANDIDATE'):f.reviewSample?t('含历史体验样本','Historical review sample'):t('门店资料候选','Restaurant candidate')}</span></div><h3>${esc(L(f,'name'))}</h3>${englishUI()?`<small class="original-name" lang="zh-CN">${esc(f.name)}</small>`:''}<p class="food-price">${esc(foodPrice(f))}</p>${f.reviewEvidence?`<p class="food-score">${t('携程公开评分','Ctrip public score')} ${f.reviewEvidence.score}/5 · ${f.reviewEvidence.count} ${t('条评价','reviews')}<small>${t('查阅快照，评价真实性未独立验证','Snapshot; review authenticity not independently verified')}</small></p>`:''}${f.localSpecialty?`<p class="food-specialty">${esc(L(f,'localSpecialty'))}</p>`:''}<p class="food-dishes">${esc(L(f,'dishes'))}</p><p class="food-address">${esc(L(f,'address'))}</p>${englishUI()?`<p class="original-name" lang="zh-CN">${esc(f.address)}</p>`:''}<p class="food-note">${esc(L(f,'caution'))}</p><div class="food-budget-actions">${foodPlan.some(p=>p.id===f.id&&p.enabled)?`<button class="secondary" data-view="plan">${t('已计入消费 · 查看','Included · view costs')}</button>`:`<button class="primary" data-add-food="${esc(f.id)}">${t('＋ 加入餐饮消费','＋ Add to dining costs')}</button>`}</div><details class="food-evidence"><summary>${t('价格、评价与来源','Price, reviews & sources')} · ${sources.length}</summary><p class="original-price">${t('原始参考：','Original reference: ')}${esc(original)}</p><p><b>${t('价格依据：','Price evidence: ')}</b>${esc(L(f,'basis'))}</p><p><b>${t('体验样本：','Review sample: ')}</b>${esc(L(f,'good'))}</p><ul>${sources.map(x=>`<li>${link(x.url,englishUI()?({'携程':'Ctrip','去哪儿':'Qunar','大众点评':'Dianping','B站':'Bilibili','餐厅官方':'Restaurant website','经营方':'Operator','羊城晚报':'Yangcheng Evening News','广西文旅（微博）':'Guangxi Tourism · Weibo','高德地图':'Amap','凤凰网':'Ifeng'}[x.platform]||x.platform):x.platform)}${x.evidenceType==='video-description'?' · '+esc(x.author)+' · '+esc(x.date)+' · '+t('仅视频简介，未完整观看','Video description only; not watched in full'):''}</li>`).join('')}${f.other?'<li>'+link(f.other,t('交叉参考','Additional source'))+'</li>':''}</ul><p class="muted">${t('查阅：','Checked: ')}${esc(f.checked||DATA.updated)} · ${t('查阅日期不等同消费发生日期','Checking date differs from the visit date')}</p></details></article>`}
function sourceTitle(s){if(I18N.chinese(lang))return s.title;const host=new URL(s.url).hostname;return (host.includes('wikipedia')?'Wikipedia':host.includes('ctrip')?'Ctrip':host.includes('qunar')?'Qunar':host.includes('ly.com')?'Tongcheng':'Tourism source')+' · '+t('',s.type==='门票依据'?'admission evidence':s.type==='图片来源'?'photo source':s.type==='百科资料'?'background information':s.type.includes('官方')?'official information':'information and visible review samples')}
function renderProvinceUpdate(){
  const current=region==='all'?(DATA.latestRegion||'广东'):region,u=DATA.provinceUpdates?.[current],box=$('#provinceUpdate');
  if(!u){box.innerHTML='';box.hidden=true;return}box.hidden=false;
  box.innerHTML=`<div><span class="eyebrow">${esc(t(`逐省更新 · ${current}第${u.batch}批`,`PROVINCE UPDATE · ${regionName(current)} ${String(u.batch).padStart(2,'0')}`))}</span><h2>${esc(t(`走进${current}，看得更深入。`,`Explore ${regionName(current)} in greater depth.`))}</h2><p>${esc(L(u,'scope'))}</p><div class="update-metrics"><span>${u.count} ${t('个景点','attractions')}</span><span>${u.cities} ${t('个城市','cities')}</span><span>${u.date}</span></div></div><button class="primary" data-region="${esc(current)}" data-latest="${u.batch}">${t('先看本批新增 →','See latest additions →')}</button>`;
}
function guideDetails(d){const g=d.guide;if(!g)return '';return `<section class="practical-guide"><div class="guide-heading"><h2>${t('出发前，先确认这几件事','Before you go')}</h2><span>${t('来源查阅','Sources checked')} · ${esc(g.checked)}</span></div><div class="guide-facts">${[['admission','门票与费用依据','Admission & price evidence'],['opening','开放与临时变更','Hours & temporary changes'],['reservation','预约与购票','Booking & tickets'],['accessibility','步行与同行提醒','Walking & accessibility']].map(([k,zh,en])=>`<article><h3>${t(zh,en)}</h3><p>${esc(k==='admission'&&TravelTickets.quote(d).expired?t('原票价政策已过有效期，现行门票待核实。','The previous tariff policy has expired; current admission is unconfirmed.'):L(g,k))}</p></article>`).join('')}</div><p class="muted">${t('来源中的原始价格保留原币种；用户预算按所选币种换算。查阅日期不代表当天现场核验。','Source prices retain their original currency; user budgets use your selected currency. Source checking is not an on-site inspection.')}</p></section>`}
function showDetail(id){
  const d=find(id);if(!d)return;if(!$('#detail').open){lastFocus=document.activeElement;detailReturnView=$$('.view').find(e=>!e.classList.contains('hidden'))?.id||'explore'}detailId=id;
  const foods=DATA.foods.filter(f=>f.recommendationStatus!=='research-only'&&f.region===d.region&&(f.place===d.name||f.city===d.city||d.region==='澳门')).slice(0,4),need=d.tier==='待调研',r=d.reviews;
  $('#detailBody').innerHTML=`<div class="detail-hero">${photo(d,true)}${ticketBadge(d)}<button class="close-detail" aria-label="${t('关闭详情','Close guide')}">×</button></div><div class="detail-main"><div class="eyebrow">${esc(regionName(d.region,true))} / ${esc(term(d.area))}</div><div class="detail-top"><h1>${esc(L(d,'name'))}</h1><span class="detail-status">${esc(term(d.tier))} · ${t('整理于','Compiled')} ${DATA.updated}</span></div>${englishUI()?`<small class="original-name" lang="zh-CN">${esc(d.name)} · ${esc(d.location)}</small>`:''}<p>${esc(L(d,'description'))}</p>${need?`<div class="notice">${t('这是待调研县域线索，尚不是完整出行攻略。','This is a county-discovery lead awaiting research, not a complete travel guide.')}</div>`:''}<div class="detail-summary"><div><small>${t('门票','Admission')}</small><b>${ticketReference(d)}</b></div><div><small>${t('适游季节 · 编辑建议','Suggested seasons · Editorial guidance')}</small><b>${esc(seasons(d.season))}</b></div><div><small>${t('建议停留 · 编辑建议','Suggested stay · Editorial guidance')}</small><b>${need?t('待细化','Not researched'):t(`${d.days} 天左右`,`About ${enCount(d.days,"day")}`)}</b></div></div><p class="photo-credit">${t('将景点加入行程，填写门票与附加费，再统一计算住宿、餐饮和交通。已确认的单一门票自动填写，其他费用请按实际情况调整。','Add this attraction to your itinerary, enter tickets and extras, then calculate accommodation, meals and transport together. Verified single-ticket prices fill automatically; adjust other expenses to your plans.')}</p>${ticketEvidence(d)}${guideDetails(d)}<div class="detail-columns"><div><h2>${t('怎么去，怎么住','Getting there and where to stay')}</h2><p>${esc(L(d,'transport'))}</p><p>${t('优先比较接驳方便的正规住宿，核查近期卫生、隔音与退改评价。本轮未核实具体酒店。','Compare registered accommodation with convenient transport. Check recent hygiene, noise and cancellation reviews. Individual hotels have not been verified.')}</p><h2>${t('吃什么','What to eat')}</h2><p>${esc(need?t('当地特色与具体店铺待调研。','Local dishes and individual restaurants need research.'):L(d,'food'))}</p></div>${d.guide?'':`<div><h2>${t('门票与开放状态','Admission and opening status')}</h2><p>${esc(d.guide?L(d.guide,'admission'):r?L(r,'ticket'):t('现行门票、开放与预约政策待官方复核。','Confirm current admission, reservations and opening status through official channels.'))}</p><h2>${t('同行人群提醒','Travel-party considerations')}</h2><p>${t('儿童票、母婴室、安全护栏、台阶、坡度及无障碍通道尚未逐项核实。按实际体力安排机动时间。','Child tickets, nursery facilities, barriers, steps, slopes and accessible routes have not all been verified. Allow spare time according to your group’s actual needs.')}</p></div>`}</div><h2>${t('网友怎么看','What visitors say')}</h2>${r?`<div class="review"><b>${t('看到的体验线索','Visible experience samples')}</b>${esc(L(r,'positive'))}</div><div class="review caution"><b>${t('分歧与样本局限','Differences and sample limitations')}</b>${esc(L(r,'negative'))}</div><p class="source-link">${link(r.url,t('查看原平台评价与游客实拍','View original reviews and visitor photos'))} · ${t('摘要不等同原文，无法独立确认每位用户到访。','English summaries translate Chinese-language sources. Each visitor’s actual visit cannot be independently confirmed.')}</p>`:`<div class="notice">${t('尚未收集到本轮核对的游客评价，不补写评论或评分。','No visitor-review samples have been checked for this entry. Reviews and ratings are not invented.')}</div>`}<h2>${t('同城美食候选与价格依据','Food candidates in this city')}</h2><p class="muted">${t('按城市关联，不表示位于景区内或附近；区县位置和交通请另核对。','Matched by city, not necessarily inside or near this attraction. Check districts and transport separately.')}</p>${foods.length?foods.map(foodCard).join('')+(d.city?`<button class="secondary" data-view="food" data-food-region="${esc(d.region)}" data-food-city="${esc(d.city)}">${t('查看本市更多美食','More food in this city')}</button>`:''):`<p>${t('本目的地暂无通过本轮核对的门店。','No individual restaurant has passed this round of source checks for this destination.')}</p>`}<h2>${t('怎么安排 · 编辑规划建议','Suggested pace · Editorial planning')}</h2>${d.guide?`<div class="trip-day"><b>${t('景点游线 · 编辑建议','Attraction route · Editorial suggestion')}</b><p>${esc(L(d.guide,'route'))}</p></div>`:need?`<p>${t('完整日程待调研；补齐交通、住宿与开放状态后再安排。','A full itinerary needs further research. Confirm transport, accommodation and opening status first.')}</p>`:`<div class="trip-day"><b>${t('第 1 天 · 抵达与熟悉周边','Day 1 · Arrive and settle in')}</b><p>${t('办理入住，确认次日开放和接驳，按体力在住宿附近慢逛。','Check in, confirm the next day’s opening and transport arrangements, then explore nearby at a comfortable pace.')}</p></div><div class="trip-day"><b>${t('第 2 天 · 主题游览','Day 2 · Explore your chosen destination')}</b><p>${esc(L(d,'description'))}</p></div><p>${t('这是节奏框架，未核验逐段距离与实时路况。','This is a pacing outline, not a verified turn-by-turn route or live transport plan.')}</p>`}<h2>${t('资料与图片来源','Sources and photo credits')}</h2><ul class="source-list">${d.sources.length?d.sources.map(s=>`<li>${link(s.url,sourceTitle(s))}${s.checked?` · ${t('查阅','Checked')} ${esc(s.checked)}`:''}</li>`).join(''):`<li>${t('详细来源待补核。','Detailed sources still need checking.')}</li>`}</ul>${d.image?`<p class="photo-credit">${d.image.en?esc(L(d.image,'caption'))+'<br>':''}${t('摄影者：','Photographer: ')}${esc(d.image.en?L(d.image,'author')||d.image.author:d.image.author)} · ${t('拍摄日期：','Photo date: ')}${esc(d.image.date||t('未明确','Not specified'))}<br>${t('版权与许可：','Copyright and license: ')}${link(d.image.licenseUrl,d.image.en?L(d.image,'license')||d.image.license:d.image.license)} · ${link(d.image.url,t('来源与署名','Source and attribution'))}${d.image.originalUrl?' · '+link(d.image.originalUrl.startsWith('https:')?d.image.originalUrl:d.image.url,d.image.originalUrl.startsWith('https:')?t('查看原图','Original image'):t('原图所在页面','Original-image page')):''}<br>${t('网页缩略展示，必要时校正方向。保留原图水印与出处；往年实景不代表当前营业与环境状态。','Thumbnail display, with orientation corrected where needed. Original watermarks and sources are retained; older photos do not establish current conditions.')}</p>`:`<p class="photo-credit">${t('暂无核对后的实景图片，当前显示文字封面。','No reference photo has been checked; a text cover is shown.')}</p>`}<div class="detail-actions"><button class="primary" data-plan="${d.id}">${t('＋ 加入我的行程','＋ Add to itinerary')}</button><button class="secondary" data-compare="${d.id}">${t('加入 / 移出对比','Toggle comparison')}</button><a class="secondary" href="https://www.amap.com/search?query=${encodeURIComponent(d.region+' '+d.name)}" target="_blank" rel="noopener noreferrer">${t('高德地图 ↗','Amap ↗')}</a><a class="secondary" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(d.region+' '+d.name)}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a><button class="secondary" id="copyPlace">${t('复制攻略链接','Copy guide link')}</button></div><p class="muted">${t('地图由第三方提供，路线以当地实际情况为准。','Maps are third-party services; confirm routes against actual local conditions.')}</p></div>`;
  if(!$('#detail').open)$('#detail').showModal();history.replaceState(null,'',`#place=${id}`);$('.close-detail').focus();$('#copyPlace').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast(t('攻略链接已复制','Guide link copied'))}catch{toast(t('请复制地址栏链接','Please copy the address-bar link.'))}};
}
function closeDetail(){$('#detail').close();detailId=null;history.replaceState(null,'','#'+detailReturnView);lastFocus?.focus()}
function stat(n,label){return `<div class="stat"><strong>${esc(n)}</strong><span>${esc(label)}</span></div>`}
const costLabels=()=>({tickets:t('景点门票与附加费','Attraction tickets & extras'),hotel:t('住宿','Accommodation'),meals:t('餐饮','Meals'),transit:t('公交地铁等','Public transport'),charter:t('打车 / 包车','Taxi / charter'),intercity:t('城际交通','Intercity transport'),longTransport:t('往返大交通','Return travel'),extra:t('其他费用','Other costs')});
function ticketReference(d){const q=TravelTickets.quote(d);if(!q.verified)return t('门票待核实','Admission not verified');if(q.free)return t('免费','Free');if(q.multiple)return q.min===0?t('分区：免费 / ','By area: free / ')+money(q.max):t('票种：','Ticket options: ')+money(q.min)+(q.min!==q.max?'–'+money(q.max):'');return money(q.min)}
function ticketBadge(d){const q=TravelTickets.quote(d),scope=q.verified?(englishUI()?d.ticket.scopeEn:d.ticket.scope):t('现行票价未确认','Current tariff unconfirmed');return `<div class="ticket-badge ${q.verified?'verified':'pending'}" title="${esc(scope)}"><strong>${q.verified?t('门票 ','Admission '):''}${esc(ticketReference(d))}</strong><small>${esc(scope)}${q.verified?' · '+t('已核对','Checked'):''}</small></div>`}
function ticketEvidence(d){const q=TravelTickets.quote(d),a=d.ticket;if(!a)return '';return `<section class="ticket-evidence ${q.verified?'verified':'pending'}"><div class="ticket-evidence-heading"><h2>${t('门票与核对状态','Admission & verification')}</h2><strong>${esc(ticketReference(d))}</strong></div><p>${esc(q.expired?t('原票价政策已过有效期，现行门票待核实。','The previous tariff policy has expired; current admission is unconfirmed.'):englishUI()?a.noteEn:a.note)}</p>${q.verified&&q.multiple?'<ul>'+a.options.map(o=>'<li>'+esc(englishUI()?o.enLabel:o.label)+' · '+(o.amount===0?t('免费','Free'):money(o.amount))+'</li>').join('')+'</ul>':''}<p class="ticket-meta">${q.verified?link(a.sourceUrl,t('查看官方票务依据','Official ticket evidence'))+' · ':''}${t('核对于','Checked')} ${esc(a.checked)}${a.sourcePublished?' · '+t('原文发布：','Published: ')+esc(a.sourcePublished):''}${a.validUntil?' · '+t('政策有效至：','Policy valid through: ')+esc(a.validUntil):''}</p><p class="muted">${t('以上为注明范围的公开票务信息，不是实时订单报价。优惠资格、预约和临时变更以官方确认为准；已确认的单一门票会自动填入预算，可自行修改。','Published admission information applies only to the stated scope; it is not a live checkout quote. Confirm concessions, reservations and temporary changes with the venue. Verified single-ticket prices fill into your budget automatically and remain editable.')}</p></section>`}

function renderCompare(){const ds=compare.map(find).filter(Boolean);if(!ds.length){$('#comparison').innerHTML=`<div class="empty"><h3>${t('还没有加入对比的目的地','Your comparison list is empty')}</h3><button class="primary" data-view="explore">${t('去探索目的地','Explore destinations')}</button></div>`;return}
 const row=(title,fn)=>`<tr><th scope="row">${title}</th>${ds.map(d=>`<td>${fn(d)}</td>`).join('')}</tr>`;
 $('#comparison').innerHTML=`<div class="notice">${t('门票参考以来源说明为准。整趟消费请添加景点后在“行程与消费”中填写计算。','See sources for admission evidence. Add attractions to Itinerary & costs to calculate the trip budget.')}</div><table class="compare-table"><thead><tr><th>${t('比较维度','Compare by')}</th>${ds.map(d=>`<th>${esc(L(d,'name'))}<br><button class="iconbtn" data-compare="${d.id}">${t('移除','Remove')}</button></th>`).join('')}</tr></thead><tbody>${row(t('所在地区','Region'),d=>esc(regionName(d.region,true)))}${row(t('旅行主题','Interest'),d=>esc(term(d.theme)))}${row(t('适游季节','Suggested seasons'),d=>esc(seasons(d.season)))}${row(t('门票与核对状态','Admission & verification'),d=>esc(ticketReference(d))+'<br><small>'+esc(englishUI()?d.ticket?.scopeEn:d.ticket?.scope)+'</small>')}${row(t('交通安排','Getting there'),d=>esc(L(d,'transport')))}${row(t('评价资料','Review sources'),d=>d.reviews?t('有可追溯入口，深度见详情','Source links available; depth varies'):t('待调研','Research pending'))}${row(t('下一步','Next step'),d=>`<button class="primary" data-detail="${d.id}">${t('查看详情','View guide')}</button> <button class="secondary" data-plan="${d.id}">${t('加入行程','Add to itinerary')}</button>`)}</tbody></table>`;
}

function addDiningFood(id){const f=DATA.foods.find(f=>f.id===id&&f.recommendationStatus!=='research-only');if(!f)return;foodPlan=TravelBudget.addFood(foodPlan,f,true);foodPlan.find(p=>p.id===id).enabled=true;save();counters();renderPlan();renderFood();toast(t('已加入并计入餐饮预算，可在行程与消费中修改。','Added to dining costs. Edit it in Itinerary & costs.'))}
function addDiningRoute(key){const g=(DATA.foodGuides||[]).find(g=>foodRouteKey(g)===key);if(!g)return;if(!foodRoutes.includes(key))foodRoutes.push(key);for(const id of g.foodIds||[]){const f=DATA.foods.find(f=>f.id===id&&f.recommendationStatus!=='research-only');if(f)foodPlan=TravelBudget.addFood(foodPlan,f,false)}save();counters();renderPlan();renderFood();toast(t('路线已加入；新增店铺默认不计费，请勾选要吃的店。已有选择保持不变。','Route saved; new shops are off until selected. Existing choices are preserved.'))}
function renderDiningTotals(c=planEstimate()){const d=c.dining;$('#diningTotals').innerHTML='<div class="dining-equation"><div><small>'+t('自填其他餐饮','Other meals entered manually')+'</small><b>'+money(d.manual.value)+'</b></div><span>＋</span><div><small>'+t('已勾选美食攻略','Selected food guides')+'</small><b>'+money(d.guide.value)+'</b></div><span>'+(currency==='CNY'?'＝':'≈')+'</span><div><small>'+t('餐饮总费用 · 全员整趟','Total dining · group / trip')+'</small><b>'+money(d.total)+'</b></div></div><p class="dining-per-person">'+t('人均餐饮整趟','Dining per person / trip')+' <b>'+money(d.perPerson)+'</b> · '+t('人均餐饮每天','Dining per person / day')+' <b>'+money(d.perPersonDay)+'</b></p>'+(!d.known?'<p class="budget-help">'+t('含待填写费用，仅合计已填写部分。未勾选的店铺不参与计算。','Some dining costs are not entered; this is a partial total. Unselected shops are excluded.')+'</p>':'');for(const p of d.stops){const el=$('[data-food-total="'+p.id+'"]');if(el)el.textContent=!p.enabled?t('未计入','Excluded'):p.cost.known?money(p.cost.value):t('价格待填写','Price not entered')}}
function renderDiningPlan(){const c=planEstimate();$('#diningRoutes').innerHTML=foodRoutes.map(key=>{const g=DATA.foodGuides.find(g=>foodRouteKey(g)===key);return '<details class="saved-food-route"><summary>'+esc(L(g,'title'))+'</summary><p>'+esc(L(g,'route'))+'</p><p class="budget-help">'+esc(L(g,'note'))+'</p><p class="budget-help">'+t('路线本身不单独收费。下方店铺勾选后计费，同一家店只保留一项；多次用餐可修改次数。','Routes have no separate charge. Select shops below; each branch appears once. Increase visits for repeat meals.')+'</p><button class="iconbtn" data-remove-food-route="'+esc(key)+'">'+t('移除路线说明（保留店铺）','Remove route notes (keep shops)')+'</button></details>'}).join('');$('#diningList').innerHTML=foodPlan.length?foodPlan.map(p=>{const f=DATA.foods.find(f=>f.id===p.id),v=p.priceCNY===null?'':Number(M.convert(p.priceCNY,currency,getRates()).toFixed(2));return '<article class="dining-stop '+(p.enabled?'':'dining-disabled')+'"><div class="dining-stop-header"><label class="dining-switch"><input type="checkbox" data-food-toggle="'+esc(p.id)+'" '+(p.enabled?'checked':'')+' aria-label="'+esc(t('计入餐饮：','Include dining: ')+L(f,'name'))+'"><span>'+esc(L(f,'name'))+'</span></label><b data-food-total="'+esc(p.id)+'"></b></div><p class="budget-help">'+t('单次人均 × 用餐人数 × 次数；留空人数跟随同行人数。','Per-person visit price × diners × visits; blank diners follows travelers.')+'</p><div class="dining-fields"><label>'+t('单次人均参考','Per person / visit')+'<div class="cost-input"><input type="number" min="0" max="100000000" step="any" value="'+v+'" data-dining-price="'+esc(p.id)+'" aria-label="'+esc(t('单次人均 · ','Per person / visit: ')+L(f,'name'))+'" placeholder="'+t('待填写','Not entered')+'"><small>'+currency+'</small></div></label><label>'+t('用餐人数','Diners')+'<input type="number" min="1" max="30" step="1" data-dining-people="'+esc(p.id)+'" value="'+(p.people??'')+'" placeholder="'+c.people+'" aria-label="'+esc(t('用餐人数 · ','Diners: ')+L(f,'name'))+'"></label><label>'+t('用餐次数','Visits')+'<input type="number" min="1" max="100" step="1" data-dining-visits="'+esc(p.id)+'" value="'+p.visits+'" aria-label="'+esc(t('用餐次数 · ','Visits: ')+L(f,'name'))+'"></label></div><details class="saved-food-guide"><summary>'+t('查看已添加的美食攻略','View saved food guide')+'</summary><p>'+esc(L(f,'dishes'))+'</p><p>'+esc(L(f,'address'))+'</p><p>'+esc(L(f,'caution'))+'</p><p class="budget-help">'+esc(L(f,'basis')||L(f,'price'))+'</p>'+link(f.url,t('查看原始来源','View original source'))+'</details><button class="iconbtn dining-remove" data-remove-food="'+esc(p.id)+'">'+t('移除店铺','Remove shop')+'</button></article>'}).join(''):'<p class="budget-help">'+t('还没有添加美食店。可单独添加，或先加入路线，再勾选店铺。','No shops saved. Add individual shops, or add a route and select its stops.')+'</p>';renderDiningTotals(c)}

function planEstimate(){return TravelBudget.calculate({people:nval('planPeople',1,30),days:nval('planDays',1,30),rooms:budgetSettings.rooms,nights:budgetSettings.nights,amounts:amountsCNY,stops:plan,foodStops:foodPlan})}
function costInput(p,key,label,value){const shown=value===null?'':Number(M.convert(value,currency,getRates()).toFixed(2));return `<label>${label}<div class="cost-input"><input type="number" min="0" max="100000000" step="any" value="${shown}" data-cost="${key}" data-stop="${p.id}" aria-label="${esc(label+' · '+L(find(p.id),'name'))}" placeholder="${t('待填写','Not entered')}"><small>${currency}</small></div></label>`}
function renderCostSummary(){const c=planEstimate(),labels=costLabels();const invalid=$$('#plan input[aria-invalid=true]').length;if(invalid)c.complete=false;$('#planSummary').innerHTML=`<div class="budget-heading"><div><span class="eyebrow">TRIP COSTS</span><h2>${t('整趟消费统计','Trip cost summary')}</h2></div><span class="budget-status ${c.complete?'complete':''}">${invalid?t('请修正标红的输入项','Correct the highlighted inputs'):c.complete?t('所有费用项已填写','All cost fields entered'):t(`${c.missing.length} 项费用待填写`,`${c.missing.length} cost fields not entered`)}</span></div><div class="stats">${stat(money(c.total),c.complete?t('全员预算合计','Whole-group budget'):t('已填费用小计 · 非完整预算','Entered costs · Incomplete budget'))}${stat(money(c.perPerson),t('人均整趟','Per person / trip'))}${stat(money(c.perPersonDay),t('人均每天','Per person / day'))}${stat(money(c.hotelPerPersonNight),t('人均每住宿晚','Accommodation / person / night'))}</div><p class="muted">${t(`${c.people} 人 / ${c.days} 天。住宿按 ${c.rooms} 间 × ${c.nights} 晚计算；摊至旅行每天的人均住宿费 ${money(c.hotelPerPersonDay)}。`,`${c.people} travelers / ${c.days} days. Accommodation: ${c.rooms} rooms × ${c.nights} nights. Accommodation averaged across travel days: ${money(c.hotelPerPersonDay)} per person per day.`)}</p><details class="cost-breakdown"><summary>${t('查看费用明细','View cost breakdown')}</summary><div class="expense-breakdown">${c.lines.map(l=>`<div><span>${labels[l.key]}${!l.known?`<small>${t('含未填写项','Includes unentered costs')}</small>`:''}</span><b>${money(l.value)}</b></div>`).join('')}</div></details><p class="budget-help">${t('空白表示待填写，不代表免费；免费或没有支出请填 0。以上是用户填写的预算，非实时价格，也不代表实际已支付。','Blank means not entered, not free. Enter 0 for free items or no expense. These are user-entered budgets, not live prices or recorded payments.')}</p>`;renderDiningTotals(c);$('#exportPlan').disabled=!!invalid;$('#printPlan').disabled=!!invalid;$('#roomCount').placeholder=t(`自动：${Math.ceil(c.people/2)} 间`,`Auto: ${Math.ceil(c.people/2)} rooms`);$('#lodgingNights').placeholder=t(`自动：${Math.max(0,c.days-1)} 晚`,`Auto: ${Math.max(0,c.days-1)} nights`)}
function renderPlan(){const c=planEstimate();renderDiningPlan();renderCostSummary();$('#roomCount').value=budgetSettings.rooms??'';$('#lodgingNights').value=budgetSettings.nights??'';
 $('#planList').innerHTML=plan.length?'<div class="stop-list">'+plan.map((p,i)=>{const d=find(p.id),q=TravelTickets.quote(d),a=d.ticket;return `<article class="plan-item cost-stop"><div class="stop-header"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="meta"><h3><button class="card-title" data-detail="${d.id}">${esc(L(d,'name'))}</button></h3><p>${esc(englishUI()?(DATA.cities.find(c=>c.region===d.region&&c.name===d.city)?.en.name||regionName(d.region)):d.city||regionName(d.region))} · ${p.ticketOrigin==='auto'?t('已填'+a.scope+' · 可修改','Reference: '+a.scopeEn+' · editable'):p.ticketOrigin==='manual'?t('使用你的价格','Using your price'):t('请选择票种或填写价格','Choose a ticket or enter a price')}</p></div><b class="stop-total" data-stop-total="${p.id}">${c.stops[i].ticket.known?money(c.stops[i].total):t('待填写','Not entered')}</b></div>${q.verified&&q.multiple?`<label class="ticket-choice">${t('选择票种','Choose a ticket')}<select data-ticket-option="${p.id}" aria-label="${esc(t('选择票种 · ','Choose a ticket: ')+L(d,'name'))}"><option value="">${t('请选择与你行程相符的票种','Choose the ticket matching your visit')}</option>${a.options.map((o,j)=>`<option value="${j}" ${p.ticketOption===j?'selected':''}>${esc(englishUI()?o.enLabel:o.label)} · ${money(o.amount)}</option>`).join('')}</select></label>`:''}<div class="stop-cost-fields">${costInput(p,'ticketPrice',t('门票单价','Ticket price'),p.ticketPrice)}<div class="ticket-multiplier">× ${c.stops[i].quantity} ${t('张','tickets')}</div><details class="stop-adjust"><summary>${t('调整人数与顺序','Adjust quantity & order')}</summary><label>${t('购票数量（留空跟随同行人数）','Ticket quantity (blank follows travelers)')}<input type="number" min="0" max="10000" step="1" data-quantity="${p.id}" value="${p.ticketCount??''}"></label><div class="actions"><button class="iconbtn" data-move="${i}" data-step="-1" ${i===0?'disabled':''} aria-label="${esc(t('上移','Move up: ')+L(d,'name'))}">↑</button><button class="iconbtn" data-move="${i}" data-step="1" ${i===plan.length-1?'disabled':''} aria-label="${esc(t('下移','Move down: ')+L(d,'name'))}">↓</button><button class="iconbtn" data-remove="${d.id}">${t('移除','Remove')}</button>${q.verified?`<button class="iconbtn" data-ticket-reset="${p.id}">${t('恢复官方参考','Use official reference')}</button>`:''}</div></details></div></article>`}).join('')+'</div>':`<div class="empty"><h3>${t('先添加想去的景点','Add attractions to your itinerary')}</h3><p>${t('已确认的单一门票会自动填写，也可先填写住宿和交通。','Verified single-ticket prices fill automatically. You can enter accommodation and transport first.')}</p><button class="primary" data-view="explore">${t('去找目的地','Explore destinations')}</button></div>`;
 $('#exportPlan').disabled=$$('#plan input[aria-invalid=true]').length>0;$('#printPlan').disabled=$('#exportPlan').disabled;
}
function exportPlan(){if($$('#plan input[aria-invalid=true]').length){toast(t('请先修正标红的输入项','Correct the highlighted inputs first.'));return}const c=planEstimate(),labels=costLabels(),text=[t('I wanna go to China · 行程与消费','I wanna go to China · Itinerary & costs'),t(`出发日期：${$('#startDate').value||'未设置'}`,`Departure: ${$('#startDate').value||'Not set'}`),`${c.people} ${t('人','travelers')} / ${c.days} ${t('天','days')}`,`${currency} · ${t('原始核算 CNY','Calculation base CNY')} · ${customRates[currency]?.date||M.reference(currency).date}`,`1 CNY = ${getRates()[currency]} ${currency}`,t('所有金额为用户预算，不代表实际已支付。空白费用未计入，不等于免费。','Amounts are user-entered budgets, not recorded payments. Unentered costs are excluded, not free.'),'',...plan.flatMap((p,i)=>{const d=find(p.id),s=c.stops[i];return[`${i+1}. ${L(d,'name')}${p.nights?t(' · 计划停留 '+p.nights+' 天',' · Planned stay '+p.nights+' days'):''}`,`${t('门票单价','Ticket price')}: ${p.ticketPrice===null?t('待填写','Not entered'):money(p.ticketPrice)} × ${s.quantity}`,`${t('已填小计','Entered subtotal')}: ${money(s.total)}`,...d.sources.map(x=>x.url),'']}),`${t('住宿计算','Accommodation')}: ${amountsCNY.roomRate===null?t('待填写','Not entered'):money(amountsCNY.roomRate)} × ${c.rooms} ${t('间','rooms')} × ${c.nights} ${t('晚','nights')}`,t('餐饮明细（全员整趟）','Dining breakdown (whole group / trip)'),`${t('自填其他餐饮','Other meals entered manually')}: ${money(c.dining.manual.value)}`,`${t('勾选美食攻略','Selected food guides')}: ${money(c.dining.guide.value)}`,...foodRoutes.map(key=>{const g=DATA.foodGuides.find(g=>foodRouteKey(g)===key);return t('已加路线（不单独收费）：','Saved route (no separate charge): ')+L(g,'title')+' · '+L(g,'route')}),...c.dining.stops.map(p=>{const f=DATA.foods.find(f=>f.id===p.id);return `${p.enabled?t('[计入]','[Included]'):t('[不计入]','[Excluded]')} ${L(f,'name')} · ${p.priceCNY===null?t('价格待填','Price not entered'):money(p.priceCNY)} × ${p.quantity} ${t('人','people')} × ${p.visits} ${t('次','visits')} = ${p.cost.known?money(p.cost.value):t('待填写','Not entered')} · ${f.url}`}),`${t('总餐饮','Total dining')}: ${money(c.dining.total)}${c.dining.known?'':t('（含未填写项）',' (incomplete)')}`,`${t('人均餐饮整趟','Dining per person / trip')}: ${money(c.dining.perPerson)}`,...c.lines.map(l=>`${labels[l.key]}: ${money(l.value)}${l.known?'':t('（含未填写项）',' (includes unentered costs)')}`),`${c.complete?t('全员预算合计','Whole-group budget'):t('已填费用小计（非完整预算）','Entered subtotal (incomplete budget)')}: ${money(c.total)}`,`${t('人均整趟','Per person / trip')}: ${money(c.perPerson)}`,`${t('人均每天','Per person / day')}: ${money(c.perPersonDay)}`,`${t('人均每住宿晚','Accommodation / person / night')}: ${money(c.hotelPerPersonNight)}`,`${t('待填写费用项','Unentered cost fields')}: ${c.missing.length}`].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`I-wanna-go-to-China-${lang}-${currency}-itinerary.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('已导出行程与消费明细','Itinerary and costs exported'))}

function renderEvidence(){$('#coverageStats').innerHTML=stat(DATA.regions.length,t('省级行政区目录','Provincial-level regions'))+stat(DATA.destinations.length,t('目的地条目（含待调研线索）','Destination entries, including leads'))+stat(DATA.destinations.filter(d=>d.image).length,t('参考实景照片','Reference photos'))+stat(DATA.destinations.filter(d=>d.reviews).length,t('含评价资料的目的地','Destinations with review sources'));$('#provinceProgress').innerHTML=DATA.regions.map(r=>{const ds=DATA.destinations.filter(d=>d.region===r.id),n=ds.filter(d=>d.sources.length).length,p=ds.filter(d=>d.tier==='待调研').length;return `<div class="progress">${esc(regionName(r.id,true))}<span>${t(`${n} 个有来源 · ${p} 个线索`,`${n} sourced · ${p} pending leads`)}</span></div>`}).join('');const allocations=[DATA.cityExpansion,...Object.values(DATA.regionalExpansions||{})].filter(Boolean),allocation=allocations.length?{method:allocations.map(a=>a.method).join(' '),methodEn:allocations.map(a=>a.methodEn).join(' '),cities:allocations.flatMap(a=>a.cities),sources:allocations.flatMap(a=>a.sources)}:null;$('#cityAllocation').innerHTML=allocation?'<p>'+esc(englishUI()?allocation.methodEn:allocation.method)+'</p><div class="allocation-grid">'+allocation.cities.map(c=>'<div><b>'+esc(englishUI()?DATA.cities.find(x=>x.name===c.city)?.en.name||c.city:c.city)+'</b><span>'+c.count+' '+t('个景点','attractions')+'</span></div>').join('')+'</div><p class="muted">'+t('判断参考：','Evidence considered: ')+allocation.sources.map(s=>link(s.url,englishUI()?t('城市与旅游公开资料','Public city and tourism information'):s.title)).join(' · ')+'</p>':'';}
function renderFood(){const q=$('#foodSearch').value.trim().toLowerCase(),r=$('#foodRegion').value,selected=$('#foodCity').value,budget=$('#foodBudget').value;const cities=[...new Set(DATA.foods.filter(f=>f.recommendationStatus!=='research-only'&&(r==='all'||f.region===r)).map(f=>f.city||f.place))];$('#foodCity').innerHTML='<option value="all">'+t('全部城市','All cities')+'</option>'+cities.map(c=>'<option value="'+esc(c)+'">'+esc(englishUI()?DATA.cities.find(v=>v.name===c)?.en.name||DATA.destinations.find(v=>v.name===c)?.en.name||c:c)+'</option>').join('');$('#foodCity').value=cities.includes(selected)?selected:'all';const city=$('#foodCity').value,list=DATA.foods.filter(f=>f.recommendationStatus!=='research-only'&&(r==='all'||r===f.region)&&(city==='all'||city===(f.city||f.place))&&(!q||[f.name,f.dishes,f.address,f.city,L(f,'name'),L(f,'dishes'),L(f,'address'),...Object.values(f.en||{})].join(' ').toLowerCase().includes(q))&&(budget==='all'||(budget==='unknown'?!f.priceCNY:f.priceCNY&&(budget==='low'?f.priceCNY.low<50:budget==='mid'?f.priceCNY.low>=50&&f.priceCNY.low<=100:f.priceCNY.low>100))));const guides=(DATA.foodGuides||[]).filter(g=>(r==='all'||g.region===r)&&(city==='all'||g.city===city)&&(!q||[g.city,g.title,g.en.title,g.route,g.en.route].join(' ').toLowerCase().includes(q)));list.sort((a,b)=>Number(!!b.localSpecialty)-Number(!!a.localSpecialty)||Number(!!b.reviewEvidence)-Number(!!a.reviewEvidence)||(b.checked||'').localeCompare(a.checked||''));$('#foodGuides').innerHTML=guides.length?'<details class="food-route-panel" '+(city!=='all'?'open':'')+'><summary>'+t('查看美食路线与安排','Food routes & planning')+' · '+guides.length+'</summary><h2>'+t('怎么吃，怎么安排','Food routes & planning')+'</h2><div class="food-guide-grid">'+guides.map(g=>'<details class="food-route-detail"><summary><span class="eyebrow">'+esc(englishUI()?DATA.cities.find(c=>c.name===g.city)?.en.name||g.city:g.city)+'</span><b>'+esc(L(g,'title'))+'</b></summary><p>'+esc(L(g,'route'))+'</p><small>'+esc(L(g,'note'))+'</small><span class="editorial-label">'+t('编辑安排建议 · 非核验步行路线','Editorial outline; walking routes not verified')+'</span><div class="route-shops">'+(g.foodIds||[]).map(id=>DATA.foods.find(f=>f.id===id)).filter(f=>f&&f.recommendationStatus!=='research-only').map(f=>'<button class="iconbtn" data-food-search="'+esc(f.name)+'">'+esc(L(f,'name'))+'</button>').join('')+'</div><button class="secondary route-add" '+(foodRoutes.includes(foodRouteKey(g))?'data-view="plan"':'data-add-food-route="'+esc(foodRouteKey(g))+'"')+'>'+t(foodRoutes.includes(foodRouteKey(g))?'查看已加入路线':'＋ 路线加入餐饮清单',foodRoutes.includes(foodRouteKey(g))?'View saved route':'＋ Add route to dining list')+'</button></details>').join('')+'</div></details>':'';$('#foodList').innerHTML=(DATA.foodDepth?'<details class="food-method"><summary>'+t('收录标准与城市分配','Selection standards & city coverage')+'</summary><p>'+esc(englishUI()?DATA.foodDepth.methodEn:DATA.foodDepth.method)+'</p></details>':'')+(list.length?'<p class="muted food-result-count">'+t(list.length+' 家候选门店 · 参考人均不是实时菜单价',list.length+' restaurant candidates · Averages are not live menu prices')+'</p><div class="food-card-grid">'+list.slice(0,foodLimit).map(foodCard).join('')+'</div>':`<div class="empty"><h3>${t('当前没有符合条件的门店','No matching restaurants')}</h3><p>${t('试试其他菜品或切换地区。','Try another dish or a different region.')}</p></div>`);$('#foodMore').hidden=list.length<=foodLimit;}
function renderAll(){applyStatic();renderRegions();renderCards();renderCompare();renderPlan();renderEvidence();renderFood();counters();if($('#detail').open&&detailId)showDetail(detailId)}
function reset(){region='all';city='all';theme='all';limit=12;$('#search').value='';$('#month').value='all';$('#party').value='all';$('#withReviews').checked=false;$('#sort').value='evidence';$$('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme==='all'));renderRegions();renderCards();save()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||!DATA)return;if(b.dataset.addFood){addDiningFood(b.dataset.addFood)}if(b.dataset.addFoodRoute){addDiningRoute(b.dataset.addFoodRoute)}if(b.dataset.removeFood){foodPlan=foodPlan.filter(p=>p.id!==b.dataset.removeFood);save();counters();renderPlan();renderFood()}if(b.dataset.removeFoodRoute){foodRoutes=foodRoutes.filter(k=>k!==b.dataset.removeFoodRoute);save();renderPlan();renderFood()}if(b.dataset.foodSearch){$('#foodSearch').value=b.dataset.foodSearch;foodLimit=8;renderFood();$('#foodList').scrollIntoView({behavior:'smooth',block:'start'})}if(b.dataset.foodCity){$('#foodRegion').value=b.dataset.foodRegion;$('#foodCity').value='all';renderFood();$('#foodCity').value=b.dataset.foodCity;foodLimit=8}if(b.dataset.view)showView(b.dataset.view);if(b.dataset.region)selectRegion(b.dataset.region,!!b.dataset.latest);if(b.dataset.city)selectCity(b.dataset.city);if(b.dataset.theme){theme=b.dataset.theme;limit=12;$$('[data-theme]').forEach(x=>x.classList.toggle('selected',x===b));renderCards()}if(b.dataset.detail)showDetail(b.dataset.detail);if(b.dataset.compare)toggleCompare(b.dataset.compare);if(b.dataset.plan)addPlan(b.dataset.plan);if(b.classList.contains('close-detail'))closeDetail();if(b.dataset.remove){plan=plan.filter(p=>p.id!==b.dataset.remove);save();counters();renderCards();renderPlan()}if(b.dataset.ticketReset){const p=plan.find(p=>p.id===b.dataset.ticketReset);Object.assign(p,TravelTickets.planTicket(find(p.id)));save();renderPlan()}if(b.id==='fillZero'){for(const id of Object.keys(amountsCNY))if(amountsCNY[id]===null)amountsCNY[id]=0;save();renderAll()}if(b.dataset.move!==undefined){const i=Number(b.dataset.move),j=i+Number(b.dataset.step);if(j>=0&&j<plan.length){[plan[i],plan[j]]=[plan[j],plan[i]];save();renderPlan()}}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail()}});$('#detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail()});
$('#provinceSelect').addEventListener('change',()=>selectRegion($('#provinceSelect').value));
$('#citySelect').addEventListener('change',()=>selectCity($('#citySelect').value));
$('#language').addEventListener('change',()=>{lang=$('#language').value;renderAll();save()});$('#currency').addEventListener('change',()=>{currency=$('#currency').value;renderAll();save()});
$('#saveRate').addEventListener('click',()=>{const v=Number($('#customRate').value);if(currency==='CNY'||!M.validRate(v)){toast(t('请输入大于零的有效汇率','Enter a valid exchange rate greater than zero.'));return}customRates[currency]={rate:v,date:new Date().toLocaleDateString('en-CA')};renderAll();save();toast(t('已保存自定义预算汇率','Custom planning rate saved'))});
$('#resetRate').addEventListener('click',()=>{delete customRates[currency];renderAll();save();toast(t('已恢复参考汇率','Reference rate restored'))});
$('#search').addEventListener('input',()=>{limit=12;if(DATA)renderCards()});for(const id of ['people','days','party','month','sort','withReviews'])$('#'+id).addEventListener('change',()=>{if(!DATA)return;limit=12;if(id==='people')$('#planPeople').value=nval('people',1,30);if(id==='days')$('#planDays').value=nval('days',1,30);save();renderCards();renderCompare();renderPlan()});
for(const id of ['planPeople','planDays','startDate'])$('#'+id).addEventListener('change',()=>{$('#'+id).value=id==='startDate'?$('#'+id).value:nval(id,1,30);if(id==='planPeople')$('#people').value=$('#planPeople').value;if(id==='planDays')$('#days').value=$('#planDays').value;save();renderPlan()});
for(const id of Object.keys(amountsCNY))$('#'+id).addEventListener('input',()=>{const el=$('#'+id),v=el.value===''?null:Number(el.value);const valid=v===null||(Number.isFinite(v)&&v>=0&&v<=1e8);el.setAttribute('aria-invalid',String(!valid));amountsCNY[id]=valid&&v!==null?M.toCNY(v,currency,getRates()):null;save();renderCostSummary()});
for(const[id,key,max]of [['roomCount','rooms',30],['lodgingNights','nights',365]])$('#'+id).addEventListener('input',()=>{const el=$('#'+id),v=el.value===''?null:Number(el.value);budgetSettings[key]=TravelBudget.integer(v,null,0,max);el.setAttribute('aria-invalid',String(v!==null&&budgetSettings[key]===null));save();renderCostSummary()});

$('#diningList').addEventListener('change',e=>{const id=e.target.dataset.foodToggle;if(!id)return;const p=foodPlan.find(p=>p.id===id);if(!p)return;p.enabled=e.target.checked;save();renderPlan();renderFood()});
$('#diningList').addEventListener('input',e=>{const el=e.target,id=el.dataset.diningPrice||el.dataset.diningPeople||el.dataset.diningVisits,p=foodPlan.find(p=>p.id===id);if(!p)return;const v=el.value===''?null:Number(el.value);let valid=true;if(el.dataset.diningPrice){const base=v===null?null:M.toCNY(v,currency,getRates());valid=v===null||TravelBudget.amount(base)!==null;p.priceCNY=valid?base:null}else if(el.dataset.diningPeople){p.people=TravelBudget.integer(v,null,1,30);valid=v===null||p.people!==null}else{valid=TravelBudget.integer(v,null,1,100)!==null;p.visits=valid?v:1}el.setAttribute('aria-invalid',String(p.enabled&&!valid));save();renderCostSummary()});

$('#planList').addEventListener('change',e=>{const id=e.target.dataset.ticketOption;if(!id)return;const p=plan.find(p=>p.id===id);Object.assign(p,TravelTickets.planTicket(find(id),{ticketOption:e.target.value===''?null:Number(e.target.value),ticketOrigin:'auto'}));save();renderPlan()});
$('#planList').addEventListener('input',e=>{const el=e.target,p=plan.find(p=>p.id===(el.dataset.stop||el.dataset.quantity||el.dataset.stay));if(!p)return;const raw=el.value===''?null:Number(el.value);if(el.dataset.stay){p.nights=TravelBudget.integer(raw,null,1,30);save();return}if(el.dataset.cost){p.ticketOrigin='manual';p.ticketOption=null;const valid=raw===null||TravelBudget.amount(raw)!==null;el.setAttribute('aria-invalid',String(!valid));p[el.dataset.cost]=valid&&raw!==null?M.toCNY(raw,currency,getRates()):null}else if(el.dataset.quantity){p.ticketCount=TravelBudget.integer(raw,null,0,10000);el.setAttribute('aria-invalid',String(raw!==null&&p.ticketCount===null))}save();renderCostSummary();const c=planEstimate(),i=plan.indexOf(p);$('[data-stop-total="'+p.id+'"]').textContent=c.stops[i].ticket.known?money(c.stops[i].total):t('待填写','Not entered');const mult=el.closest('.cost-stop').querySelector('.ticket-multiplier');if(mult)mult.textContent='× '+c.stops[i].quantity+' '+t('张','tickets')});
$('#reset').onclick=reset;$('#emptyReset').onclick=reset;$('#loadMore').onclick=()=>{limit+=12;renderCards()};$('#exportPlan').onclick=exportPlan;$('#printPlan').onclick=()=>window.print();for(const id of ['foodRegion','foodCity','foodBudget'])$('#'+id).addEventListener('change',()=>{foodLimit=8;if(id==='foodRegion')$('#foodCity').value='all';renderFood()});$('#foodSearch').addEventListener('input',()=>{foodLimit=8;renderFood()});$('#foodMore').addEventListener('click',()=>{foodLimit+=8;renderFood()});
window.addEventListener('hashchange',()=>{if(!DATA)return;const h=location.hash.slice(1);if(h.startsWith('place=')){if(find(h.slice(6)))showDetail(h.slice(6));else showView('explore')}else{if($('#detail').open)$('#detail').close();detailId=null;showView(h)}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&DATA&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();showView('explore');$('#search').focus()}});
async function init(){captureStatic();try{const r=await fetch('data.json');if(!r.ok)throw Error('HTTP '+r.status);DATA=await r.json();loadState();renderAll();if(!storageOK)toast(t('无法读取浏览器存储，请及时导出行程。','Browser storage could not be read. Export your itinerary as a backup.'));const hash=location.hash.slice(1);if(hash.startsWith('place=')&&find(hash.slice(6))){showView('explore');showDetail(hash.slice(6))}else showView(hash||'explore')}catch(e){console.error(e);$('#explore').innerHTML='<div class="error"><h2>资料暂时未能载入 / Could not load the guide</h2><p>请刷新页面重试。 / Please refresh and try again.</p><button class="primary" onclick="location.reload()">重新载入 / Reload</button></div>'}}
const localeObserver=new MutationObserver(()=>{if(DATA)I18N.localizeDom(document.body,lang)});localeObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
init();
